#include "plugin.h"
#include "table_defaults.h"
#include <imgui_internal.h>
#include <ctime>
#include <cstdio>
namespace {
const ImVec4 green{.49f,.87f,.46f,1},gold{1,.78f,.34f,1},muted{.62f,.67f,.70f,1};
void right(const char* value){ImGui::SetCursorPosX(ImGui::GetCursorPosX()+std::max(0.f,ImGui::GetContentRegionAvail().x-ImGui::CalcTextSize(value).x));ImGui::TextUnformatted(value);}
}
void DXNotebook::tableTabs(){
 if(!ImGui::BeginTabBar("reception_views",ImGuiTabBarFlags_FittingPolicyScroll))return;
 const bool restoring=!tabsApplied_;const int desired=tableTab_;int active=-1;const char* tabs[]={"Unique stations","All messages","Countries heard"};for(int i=0;i<3;i++)if(ImGui::BeginTabItem(tabs[i],nullptr,restoring&&i==desired?ImGuiTabItemFlags_SetSelected:0)){active=i;ImGui::EndTabItem();}ImGui::EndTabBar();tabsApplied_=true;if(!restoring&&active>=0&&tableTab_!=active){tableTab_=active;tableQuery_.offset=0;save();refresh();}
}
void DXNotebook::countryTable(const std::vector<dx::CountrySummary>& rows){
 auto snapshot=engine_->snapshot();ImGui::TextDisabled("%zu countries | distinct senders | distances: %s",rows.size(),dx::distanceUnit(distanceMiles_));
 float scale=ImGui::GetCurrentWindow()->FontWindowScale;ImGui::SetWindowFontScale(scale*.85f);ImGui::TextWrapped("Averages use each sender's latest matching reception. Unknown distances are excluded.");ImGui::SetWindowFontScale(scale);
 const char* columns[]={"Country","Stations","Avg. distance","Avg. SNR dB","Last 5 senders","Last heard"};
 dx::resetTableLayout("country_summary",resetTableLayouts_,4);
 if(!ImGui::BeginTable("country_summary",6,ImGuiTableFlags_Resizable|ImGuiTableFlags_Reorderable|ImGuiTableFlags_Hideable|ImGuiTableFlags_Sortable|ImGuiTableFlags_ScrollX|ImGuiTableFlags_ScrollY|ImGuiTableFlags_RowBg|ImGuiTableFlags_BordersInnerV|ImGuiTableFlags_SizingFixedFit))return;
 for(int i=0;i<6;i++)ImGui::TableSetupColumn(columns[i],i==5?ImGuiTableColumnFlags_DefaultSort|ImGuiTableColumnFlags_PreferSortDescending:0,i==0?170:i==2?ImGui::CalcTextSize("Avg. distance").x+24:i==4?340:i==5?ImGui::CalcTextSize("2026-10-14 23:59:59 +03:00").x:0);
 auto* layout=GImGui->CurrentTable;if(!countryColumnsApplied_){if(countryColumns_.size()==6)for(int i=0;i<6;i++){const auto& pref=countryColumns_[size_t(i)];auto& col=layout->Columns[i];col.DisplayOrder=ImGuiTableColumnIdx(pref.order);layout->DisplayOrderToIndex[pref.order]=ImGuiTableColumnIdx(i);if(pref.width>0){col.WidthRequest=pref.width;col.AutoFitQueue=0;}ImGui::TableSetColumnEnabled(i,pref.visible);}ImGui::TableSetColumnSortDirection(countrySort_,countryDescending_?ImGuiSortDirection_Descending:ImGuiSortDirection_Ascending,false);layout->IsSettingsDirty=true;countryColumnsApplied_=true;}
 ImGui::TableSetupScrollFreeze(0,1);ImGui::TableHeadersRow();if(auto* sort=ImGui::TableGetSortSpecs();sort&&sort->SpecsDirty&&sort->SpecsCount){countrySort_=sort->Specs[0].ColumnIndex;countryDescending_=sort->Specs[0].SortDirection==ImGuiSortDirection_Descending;sort->SpecsDirty=false;save();refresh();}
 ImGuiListClipper clipper;clipper.Begin(int(rows.size()));while(clipper.Step())for(int i=clipper.DisplayStart;i<clipper.DisplayEnd;i++){const auto& row=rows[size_t(i)];ImGui::PushID(row.country.c_str());ImGui::TableNextRow();if(!row.latestSenders.empty())for(const auto& arrival:snapshot->arrivals)if(arrival.key==row.latestSenders.front().key()){float opacity=dx::arrivalOpacity((dx::monotonicMs()-arrival.observedMs)/1000.);if(opacity>0)ImGui::TableSetBgColor(ImGuiTableBgTarget_RowBg1,ImGui::ColorConvertFloat4ToU32({.49f,.87f,.46f,opacity*.24f}));break;}
  bool record=row.country==snapshot->stats.farthestCountry&&snapshot->stats.farthest>0;ImGui::TableNextColumn();countryFlag(row.country);auto color=record?gold:snapshot->stats.isNewestCountry(row.country)?green:ImGui::GetStyleColorVec4(ImGuiCol_Text);ImGui::PushStyleColor(ImGuiCol_Text,color);auto at=ImGui::GetCursorScreenPos();if(ImGui::Selectable(row.country.c_str(),selectedCountry_==row.country,ImGuiSelectableFlags_SpanAllColumns|ImGuiSelectableFlags_AllowDoubleClick)&&ImGui::IsMouseDoubleClicked(0)){selected_.reset();selectedCountry_=row.country;detailsOpen_=true;detailsOffset_=0;engine_->selectCountry(row.country);}if(record)ImGui::GetWindowDrawList()->AddText({at.x+.65f,at.y},ImGui::ColorConvertFloat4ToU32(color),row.country.c_str());ImGui::PopStyleColor();if(ImGui::IsItemHovered()&&record)ImGui::SetTooltip("Contains the farthest station in the statistics scope.");if(ImGui::BeginPopupContextItem("country_actions")){if(ImGui::MenuItem("Filter this country")){tableFilter_.country=row.country;save();refresh();}ImGui::EndPopup();}
  char number[48];ImGui::TableNextColumn();std::snprintf(number,sizeof(number),"%lld",row.stations);right(number);ImGui::TableNextColumn();if(row.averageKm)std::snprintf(number,sizeof(number),"%.0f",dx::distanceDisplay(*row.averageKm,distanceMiles_));else std::snprintf(number,sizeof(number),"--");right(number);if(ImGui::IsItemHovered())ImGui::SetTooltip("Mean grid-center distance of %lld located senders out of %lld. Each sender contributes once.",row.distanceSamples,row.stations);
  ImGui::TableNextColumn();std::snprintf(number,sizeof(number),"%+.1f",row.averageSnr);right(number);if(ImGui::IsItemHovered())ImGui::SetTooltip("Arithmetic mean of the latest matching SNR estimates in dB, measured by this receiver. This is not combined signal power.");
  ImGui::TableNextColumn();auto senders=dx::senderList(row);ImGui::TextUnformatted(senders.c_str());if(ImGui::IsItemHovered())ImGui::SetTooltip("%s",senders.c_str());ImGui::TableNextColumn();const auto age=dx::ageText(row.lastUtc,time(nullptr));right(age.c_str());ImGui::PopID();
 }ImGui::EndTable();if(!ImGui::IsMouseDown(0)){std::vector<dx::TableColumnSetting> prefs;for(int i=0;i<6;i++){const auto& col=layout->Columns[i];prefs.push_back({col.DisplayOrder,col.WidthRequest>0?std::round(col.WidthRequest*2)/2:0,col.IsUserEnabledNextFrame});}auto json=dx::columnSettingsJson(prefs);if(json!=dx::columnSettingsJson(countryColumns_)){countryColumns_=std::move(prefs);engine_->settings({{"country_columns",json}});}}
}
